diff --git a/arch/x86/kvm/vmx.c b/arch/x86/kvm/vmx.c
index 87b453eeae40f43a03865f6918995faa645fa061..2beb77c319e8d156a1cb1daa8169fd7a7c357f4f 100644
--- a/arch/x86/kvm/vmx.c
